import{_ as o,C as r,o as n,c as s,j as e,a,E as l,a2 as i}from"./chunks/framework.CdvW4CUT.js";const f=JSON.parse('{"title":"通知渠道","description":"CertHub 的 10 种通知渠道、配置要点、业务返回码校验与常见静默失败。","frontmatter":{"title":"通知渠道","description":"CertHub 的 10 种通知渠道、配置要点、业务返回码校验与常见静默失败。"},"headers":[],"relativePath":"docs/notify.md","filePath":"docs/notify.md","lastUpdated":null}'),c={name:"docs/notify.md"};function h(p,t,b,u,k,P){const d=r("NotifyChannels");return n(),s("div",null,[t[0]||(t[0]=e("h1",{id:"通知渠道",tabindex:"-1"},[a("通知渠道 "),e("a",{class:"header-anchor",href:"#通知渠道","aria-label":'Permalink to "通知渠道"'},"​")],-1)),t[1]||(t[1]=e("p",null,[e("strong",null,"通知渠道"),a(" 里维护发送目标，流水线的「发送通知」任务与系统的到期提醒都用它。")],-1)),t[2]||(t[2]=e("h2",{id:"支持的渠道",tabindex:"-1"},[a("支持的渠道 "),e("a",{class:"header-anchor",href:"#支持的渠道","aria-label":'Permalink to "支持的渠道"'},"​")],-1)),l(d),t[3]||(t[3]=i(`<table tabindex="0"><thead><tr><th>渠道</th><th>需要准备</th></tr></thead><tbody><tr><td>邮件通知</td><td>SMTP 服务器、端口、账号、授权码 / 密码、发件人</td></tr><tr><td>Webhook</td><td>一个能接收 POST 的地址，可自定义 body 模板</td></tr><tr><td>钉钉机器人</td><td>群机器人 Webhook 地址（含 <code>access_token</code>），可选加签</td></tr><tr><td>飞书机器人</td><td>群机器人 Webhook 地址</td></tr><tr><td>企业微信机器人</td><td>群机器人 Webhook 地址（<code>key=</code> 参数）</td></tr><tr><td>AnPush / Server 酱 / PushPlus</td><td>各自的 token</td></tr><tr><td>Telegram</td><td>Bot Token + Chat ID</td></tr><tr><td>Bark</td><td>设备推送地址（<code>https://api.day.app/&lt;key&gt;</code>）</td></tr></tbody></table><h2 id="配置步骤" tabindex="-1">配置步骤 <a class="header-anchor" href="#配置步骤" aria-label="Permalink to &quot;配置步骤&quot;">​</a></h2><ol><li><strong>通知渠道 → 新建渠道</strong>，选类型，填字段。</li><li>点「测试」，系统会真的发一条消息出去 —— 很多渠道的 token 错误只在响应体里体现，不真发一次看不出来。</li><li>回到流水线，在最后加一个 <strong>通知</strong> 任务，选择这条渠道。</li><li>在 <strong>系统设置 → 通知</strong> 里把默认渠道设好，到期提醒会走它。</li></ol><h2 id="一个容易踩的坑-http-200-不等于发送成功" tabindex="-1">一个容易踩的坑：HTTP 200 不等于发送成功 <a class="header-anchor" href="#一个容易踩的坑-http-200-不等于发送成功" aria-label="Permalink to &quot;一个容易踩的坑：HTTP 200 不等于发送成功&quot;">​</a></h2><p>钉钉、企业微信、飞书、Server 酱、PushPlus 这些渠道，<strong>token 错了、机器人被移出群、被限流时依然返回 HTTP 200</strong>，只在响应体里给一个非成功的 <code>errcode</code> / <code>code</code>。只看 HTTP 状态码会把「没发出去」记成「执行成功」—— 证书到期提醒静默丢失，比报错更难发现。</p><p>所以每个渠道发送后都会过一遍业务码校验：</p><table tabindex="0"><thead><tr><th>渠道</th><th>成功值</th></tr></thead><tbody><tr><td>钉钉 / 企业微信</td><td><code>errcode == 0</code></td></tr><tr><td>飞书</td><td><code>code == 0</code></td></tr><tr><td>PushPlus / Bark</td><td><code>code == 200</code></td></tr><tr><td>Server 酱</td><td><code>code == 0</code></td></tr><tr><td>Telegram</td><td><code>ok == true</code></td></tr></tbody></table><p>另外错误信息里只保留主机名：钉钉 / 飞书把 token 放在 query，Telegram / Bark 放在 path，整条 URL 打进执行日志等于把密钥写进历史记录。</p><h2 id="通知任务放在哪" tabindex="-1">通知任务放在哪 <a class="header-anchor" href="#通知任务放在哪" aria-label="Permalink to &quot;通知任务放在哪&quot;">​</a></h2><p>推荐结构：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阶段 1  申请证书</span></span>
<span class="line"><span>阶段 2  部署证书</span></span>
<span class="line"><span>阶段 3  通知        ← Notify 任务，成功/失败都发</span></span></code></pre></div><p>如果希望「申请失败也要通知」，在申请任务上配「失败后跳转 → 通知任务」；或者在系统设置里开启到期提醒，由平台统一推送。</p><h2 id="消息内容" tabindex="-1">消息内容 <a class="header-anchor" href="#消息内容" aria-label="Permalink to &quot;消息内容&quot;">​</a></h2><p>通知正文包含：流水线名称、运行结果、耗时、证书域名与到期时间、失败任务的错误摘要。日志里的完整堆栈不会进通知 —— 业务异常只有一行中文结论。</p>`,14))])}const T=o(c,[["render",h]]);export{f as __pageData,T as default};
